const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const human=value=>String(value??'').replaceAll('_',' ');
const option=(value,label,selected)=>`<option value="${h(value)}"${String(value)===String(selected)?' selected':''}>${h(label)}</option>`;
const editable=binding=>['narrative','extension','report_value'].includes(binding?.type||binding?.kind||binding?.behavior);
const valueType=field=>field.valueType||field.dataType||field.type||'text';
const repeated=field=>['array','repeat_table'].includes(valueType(field));
const columns=field=>(field.columns||[]).map(column=>({...column,key:column.key||column.id}));
const rowLimit=field=>Math.max(0,Math.min(500,Math.floor(2000/Math.max(1,columns(field).length)),field.maxRows??500,field.capacity??500,field.anchor?.endRow?field.anchor.endRow-field.anchor.startRow+1:500));
const valueControl=(field,value,{name='value',cell=false}={})=>{const type=valueType(field),attrs=`name="${h(name)}"${cell?' data-cts-cell':''}${field.required?' required':''}`,blank=option('','Choose a value',value);if(field.allowedValues)return `<select ${attrs}>${blank}${field.allowedValues.map(v=>option(v,v,value)).join('')}</select>`;if(type==='boolean')return `<select ${attrs}>${blank}${option('true','Yes',String(value))}${option('false','No',String(value))}</select>`;if(['number','integer','date'].includes(type))return `<input ${attrs} type="${type==='date'?'date':'number'}"${type==='number'?' step="any"':type==='integer'?' step="1"':''}${field.minimum!==undefined?` min="${h(field.minimum)}"`:''}${field.maximum!==undefined?` max="${h(field.maximum)}"`:''} value="${h(value??'')}">`;return `<textarea ${attrs} maxlength="${h(field.maxLength||50000)}"${cell?' rows="2"':''}>${h(text(value))}</textarea>`;};
const fieldLabel=field=>`${h(field.label||field.key||field.id)}${field.unit?` (${h(field.unit)})`:''}${field.required?' · required':''}`;
const repeatRow=(field,value,index)=>`<fieldset data-cts-repeat-row style="min-width:0"><legend>Row ${index+1}</legend><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,12rem),1fr));gap:.75rem;min-width:0">${columns(field).map(column=>`<label>${fieldLabel(column)}${valueControl(column,value?.[column.key]??'',{name:column.key,cell:true})}</label>`).join('')}</div><button type="button" data-cts-action="repeat-remove">Remove row ${index+1}</button></fieldset>`;
function repeatControl(field,value){const declared=columns(field),rows=Array.isArray(value)?value:[];if(!declared.length)return '<p role="alert">Declare the repeated columns in the template definition before editing this report-only table.</p>';if(rows.length*declared.length>2000)return '<p role="alert">This report-only table exceeds the 2,000-cell editor limit. Correct its definition or retained report values before editing.</p>';return `<div data-cts-repeat>${rows.map((row,index)=>repeatRow(field,row,index)).join('')}</div><p data-cts-repeat-limit>${rows.length} of ${rowLimit(field)} rows · report-only values. Saving changes resets the value review and generated output.</p><button type="button" data-cts-action="repeat-add"${rows.length>=rowLimit(field)?' disabled':''}>Add row</button>`;}
function readonlyValue(field,value){if(!repeated(field)||!Array.isArray(value))return `<pre>${h(text(value??''))}</pre>`;const declared=columns(field),keys=declared.length?declared.map(column=>column.key):[...new Set(value.flatMap(row=>row&&typeof row==='object'?Object.keys(row):[]))],labels=new Map(declared.map(column=>[column.key,fieldLabel(column)]));return value.length?value.map((row,index)=>`<fieldset style="min-width:0" data-cts-canonical-row><legend>Row ${index+1} · shared records</legend><dl>${keys.map(key=>`<dt>${labels.get(key)||h(key)}</dt><dd>${h(text(row?.[key]??''))}</dd>`).join('')}</dl></fieldset>`).join(''):'<p>No matching shared records.</p>';}
function typedValue(raw,field){const value=String(raw??''),label=field.label||field.key||field.id||'Value',type=valueType(field);if(!value.trim()){if(field.required)throw Error(`${label} is required.`);return ['number','integer','date','boolean'].includes(type)?null:'';}let typed=value;if(type==='boolean'){if(!['true','false'].includes(value))throw Error(`${label} requires Yes or No.`);typed=value==='true';}if(['number','integer'].includes(type)){typed=Number(value);if(!Number.isFinite(typed)||(type==='integer'||field.integer===true)&&!Number.isInteger(typed))throw Error(`${label} requires a valid ${type}.`);if(field.minimum!==undefined&&typed<field.minimum||field.maximum!==undefined&&typed>field.maximum)throw Error(`${label} is outside the template numeric bounds.`);}if(type==='date'&&(!/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(Date.parse(value))||new Date(value).toISOString().slice(0,10)!==value))throw Error(`${label} requires a valid date.`);if(field.allowedValues){const controlled=field.allowedValues.find(item=>String(item)===value);if(controlled===undefined)throw Error(`${label} requires a listed value.`);typed=controlled;}if(value.length>(field.maxLength||50000))throw Error(`${label} exceeds its length limit.`);return typed;}
const evidenceEntities=['assertions','findings','actions','measurements','missions','verifications','requirements','monitoringObligations','indicators'];
const evidenceOptions=(engagement,citations=[])=>evidenceEntities.flatMap(entity=>(engagement?.[entity]||[]).map(row=>`<option value="${h(entity==='assertions'?row.id:`${entity}:${row.id}`)}"${citations.some(item=>typeof item==='string'?entity==='assertions'&&item===row.id:(item.entity||'assertions')===entity&&(item.id||item.assertionId)===row.id)?' selected':''}>${h(entity)} · ${h(row.id)} · ${h(row.locator||row.description||row.title||row.name||row.rationale||'')}</option>`)).join('');
const parseCitations=values=>values.map(value=>value.includes(':')?{entity:value.slice(0,value.indexOf(':')),id:value.slice(value.indexOf(':')+1)}:value);
const text=value=>typeof value==='string'?value:JSON.stringify(value??'',null,2);
const manualTypes=['text','number','integer','date','boolean'];
const manualName=(name,column=false)=>column?`column${name[0].toUpperCase()}${name.slice(1)}`:name;
function manualConstraints(raw={},{column=false}={}){const name=key=>manualName(key,column),numeric=['number','integer'].includes(raw.type||'text');return `<label>Value type<select name="${name('type')}" data-cts-manual-type>${manualTypes.map(type=>option(type,type,raw.type||'text')).join('')}</select></label><label class="cts-check"><input type="checkbox" name="${name('required')}"${raw.required?' checked':''}> Required ${column?'cell':'report input'}</label><label>Unit, exactly as reviewed in the source<input name="${name('unit')}" maxlength="120" value="${h(raw.unit||'')}" placeholder="e.g. mg/L; leave blank if unspecified"></label>${numeric?`<label>Minimum<input name="${name('minimum')}" type="number" step="any" value="${h(raw.minimum??'')}"></label><label>Maximum<input name="${name('maximum')}" type="number" step="any" value="${h(raw.maximum??'')}"></label>${raw.type==='number'?`<label class="cts-check"><input name="${name('integer')}" type="checkbox"${raw.integer?' checked':''}> Whole numbers only</label>`:''}`:''}${(raw.type||'text')==='text'?`<label>Maximum text length<input name="${name('maxLength')}" type="number" min="1" max="50000" step="1" value="${h(raw.maxLength??'')}"></label>`:''}<label>Allowed values, one per line (optional)<textarea name="${name('allowedValues')}" maxlength="50000" rows="2">${h(raw.allowedValues||'')}</textarea></label>`;}
function readManualConstraints(node,{column=false,previous={}}={}){const control=key=>node.querySelector(`[name="${manualName(key,column)}"]`),raw={...previous};for(const key of ['type','unit','minimum','maximum','maxLength','allowedValues'])if(control(key))raw[key]=control(key).value;for(const key of ['required','integer'])if(control(key))raw[key]=control(key).checked;return raw;}
function manualDefinition(raw){const type=raw.type||'text',field={type,required:Boolean(raw.required)};if(!manualTypes.includes(type))throw Error('Choose a supported scalar value type.');if(raw.unit?.trim())field.unit=raw.unit.trim();if(['number','integer'].includes(type)){for(const key of ['minimum','maximum'])if(String(raw[key]??'').trim()){field[key]=Number(raw[key]);if(!Number.isFinite(field[key]))throw Error('Use finite numerical bounds.');}if(field.minimum!==undefined&&field.maximum!==undefined&&field.minimum>field.maximum)throw Error('The reviewed minimum exceeds the maximum.');if(type==='number'&&raw.integer)field.integer=true;}if(type==='text'&&String(raw.maxLength??'').trim()){field.maxLength=Number(raw.maxLength);if(!Number.isSafeInteger(field.maxLength)||field.maxLength<1||field.maxLength>50000)throw Error('Use a text length from 1 to 50,000 characters.');}if(raw.allowedValues?.trim()){const entries=raw.allowedValues.split(/\r?\n/).map(value=>value.trim()).filter(Boolean);if(entries.length>100)throw Error('Use at most 100 allowed values.');field.allowedValues=entries.map(value=>typedValue(value,{...field,required:true}));if(new Set(field.allowedValues.map(value=>JSON.stringify(value))).size!==entries.length)throw Error('Each allowed value must be distinct.');}return field;}
