  const version=()=>state.template?.versions.find(row=>row.version===Number(state.version))||state.template?.versions.at(-1);
  const field=()=>version()?.analysis.fields.find(row=>row.id===state.fieldId)||version()?.analysis.fields[0];
  const binding=()=>version()?.bindings.find(row=>row.fieldId===field()?.id);
  const draftKey=id=>`${state.report?.id}:${state.report?.revision}:${id}`;
  function captureValueDraft(form){const f=version()?.analysis.fields.find(row=>row.id===form.dataset.field);if(!f)return;const data=new view.FormData(form),value=repeated(f)?[...form.querySelectorAll('[data-cts-repeat-row]')].map(row=>Object.fromEntries(columns(f).map(column=>[column.key,[...row.querySelectorAll('[data-cts-cell]')].find(control=>control.name===column.key)?.value??'']))):data.get('value');const draft={value,kind:data.get('kind')||'human',citations:parseCitations(data.getAll('citations')),privacyAttestation:data.has('privacyAttestation')};valueDrafts.set(draftKey(f.id),draft);return draft;}
  const assistantSupports=task=>state.assistant?.available&&(!Array.isArray(state.assistant.supportedTasks)||state.assistant.supportedTasks.includes(task));
  const actor=()=>{if(verifiedActor){if(state.actorId&&state.actorId!==verifiedActor)throw Error('The signed-in identity supplies report authorship.');return verifiedActor;}if(!state.actorId)throw Error('Select the assigned team member acting on this work.');return state.actorId;};
  function url(blob){const value=view.URL.createObjectURL(blob);urls.add(value);return value;}
  function download(blob,name){const a=document.createElement('a');a.href=url(blob);a.download=name;root.append(a);a.click();a.remove();const value=a.href;view.setTimeout(()=>{view.URL.revokeObjectURL(value);urls.delete(value);},1000);}
  function clearPreviews(){for(const value of previewUrls){view.URL.revokeObjectURL(value);urls.delete(value);}previewUrls=[];state.preview=[];}
  async function sourcePreview(page=1){const value=url(await api(`/api/client-templates/${state.template.id}/reference?${new URLSearchParams({version:state.version,format:'page',page})}`,{binary:true}));if(state.sourcePreview?.url){view.URL.revokeObjectURL(state.sourcePreview.url);urls.delete(state.sourcePreview.url);}state.sourcePreview={templateId:state.template.id,version:Number(state.version),page:Number(page),url:value};}
  async function previews(page=1){state.previewPage=Number(page);clearPreviews();const report=state.report,artifact=report?.artifacts.find(row=>row.id===report.latestArtifactId);if(!artifact)return;for(const format of ['originalPages','pages','diffs']){const item=artifact.files[format]?.find(row=>row.page===state.previewPage);if(!item)continue;const value=url(await api(`/api/template-reports/${report.id}/artifacts/${artifact.id}?${new URLSearchParams({format,page:item.page})}`,{binary:true}));previewUrls.push(value);state.preview.push({format,url:value});}}
  async function directory(){state.directory=await api('/api/client-templates');state.reports=(await api(`/api/template-reports?${new URLSearchParams({...(state.engagementId?{engagementId:state.engagementId}:{})})}`)).reports||[];}
  async function loadEngagement(id){valueDrafts.clear();clearPreviews();state.nativeJob=null;state.nativeJobs=null;state.mappingDraft=null;state.mappingSuggestions=[];state.narrativeSuggestions=[];state.learning=null;state.engagementId=id;state.engagement=id?await api(`/api/engagements/${id}`):null;const actors=[...new Set(Object.values(state.engagement?.roles||{}).flat())];if(!actors.includes(state.actorId))state.actorId='';state.cycleId=state.engagement?.cycles?.find(row=>row.id===state.cycleId)?.id||'';state.report=null;}
  async function openTemplate(id){valueDrafts.clear();clearPreviews();state.nativeJob=null;state.nativeJobs=null;state.mappingDraft=null;state.mappingSuggestions=[];state.narrativeSuggestions=[];state.template=id?await api(`/api/client-templates/${id}`):null;state.version=state.template?.versions.at(-1)?.version;state.fieldId=version()?.analysis.fields[0]?.id;state.report=null;}
  async function templateCommand(command){state.template=await api(`/api/client-templates/${state.template.id}/commands`,{body:{expectedRevision:state.template.revision,actorId:actor(),command:{...command,version:Number(state.version)}}});state.version=state.template.versions.at(-1)?.version;await directory();}
  async function reportCommand(command){const prior=state.report,prefix=`${prior.id}:${prior.revision}:`;state.report=await api(`/api/template-reports/${state.report.id}/commands`,{body:{expectedRevision:state.report.revision,actorId:actor(),command}});for(const [key,draft]of [...valueDrafts])if(key.startsWith(prefix)){valueDrafts.delete(key);const fieldId=key.slice(prefix.length);if(state.report.id===prior.id&&!(command.type==='value-save'&&command.fieldId===fieldId))valueDrafts.set(draftKey(fieldId),draft);}await directory();}
  function review(form){const data=new view.FormData(form);if(!data.has('attested'))throw Error('Confirm that you reviewed the selected content and layout.');const statement=String(data.get('statement')||'').trim();if(!statement)throw Error('Record the review findings.');return {attested:true,statement,formattingStatement:String(data.get('formattingStatement')||statement)};}
  function reviewControls(){return `<label>Review findings<textarea name="statement" required maxlength="4000"></textarea></label><label>Layout findings<textarea name="formattingStatement" maxlength="4000"></textarea></label><label class="cts-check"><input name="attested" type="checkbox" required> I have reviewed the selected content and its source context.</label>`;}
  const officeContext=()=>JSON.stringify([state.accountId,state.engagementId,state.template?.id,version()?.version,version()?.sourceSha256]);
  function officeInput(){const context=officeContext();if(officeDraft?.context!==context)officeDraft={context,mode:'scalar',filter:'',target:'',id:'',label:'',type:'text',columns:[]};return officeDraft;}
  function captureOffice(form){const draft=officeInput();if(form.dataset.context!==draft.context)return draft;for(const key of ['mode','target','blankCell','id','label','statement','maxRows','startRow','endRow']){const control=form.querySelector(`[name="${key}"]`);if(control)draft[key]=control.value;}draft.filter=form.querySelector('[data-cts-anchor-search]')?.value||'';draft.attested=Boolean(form.querySelector('[name="sourceReviewed"]')?.checked);draft.required=Boolean(form.querySelector('[name="required"]')?.checked);const scalar=form.querySelector('[data-cts-manual-scalar]');if(scalar)Object.assign(draft,readManualConstraints(scalar,{previous:draft}));draft.columns=[...form.querySelectorAll('[data-cts-manual-column]')].map((node,index)=>({...readManualConstraints(node,{column:true,previous:draft.columns[index]}),key:node.querySelector('[name="columnKey"]').value,label:node.querySelector('[name="columnLabel"]').value,source:node.querySelector('[name="sourceColumn"]')?.value??draft.columns[index]?.source}));return draft;}
  function officeAnchors(mode='scalar'){const v=version(),structure=v?.analysis.structure||{},pins={sourceSha256:v?.sourceSha256};if(mode==='repeat')return [...(structure.tables||[]).flatMap(table=>[...new Set((table.cells||[]).map(cell=>cell.row))].flatMap(row=>{const cells=table.cells.filter(cell=>cell.row===row).sort((a,b)=>a.cell-b.cell);return cells.length>0&&cells.length<=100&&cells.every((cell,index)=>!cell.merged&&cell.cell===index)?[{label:`${table.part} · table ${table.index}, row ${row} · ${cells.map(cell=>cell.text||'(blank)').join(' | ')}`,cells,anchor:{kind:'docx_manual_repeat_row',part:table.part,table:table.index,row,sourceTexts:cells.map(cell=>cell.text||''),...pins}}]:[];})),...(structure.sheets||[]).filter(sheet=>!sheet.protected&&worksheetBounds(sheet)).map(sheet=>({label:`${sheet.name||sheet.part} · fixed rows within ${sheet.dimension}`,sheet,anchor:{kind:'xlsx_manual_repeat_range',part:sheet.part,...pins}}))];return [...(structure.paragraphs||[]).filter(row=>!row.inTable).map(row=>({label:`${row.part} · paragraph ${row.index} · ${row.text||'(blank)'}`,anchor:{kind:'docx_paragraph',part:row.part,paragraph:row.index,sourceText:row.text||'',...pins}})),...(structure.tables||[]).flatMap(table=>(table.cells||[]).filter(cell=>!cell.merged).map(cell=>({label:`${table.part} · table ${table.index}, row ${cell.row}, cell ${cell.cell} · ${cell.text||'(blank)'}`,anchor:{kind:'docx_table_cell',part:table.part,table:table.index,row:cell.row,cell:cell.cell,sourceText:cell.text||'',...pins}}))),...(structure.sheets||[]).filter(sheet=>!sheet.protected).flatMap(sheet=>[{label:`${sheet.name||sheet.part} · select a blank cell address`,blank:true,anchor:{kind:'xlsx_cell',part:sheet.part,sourceText:'',...pins}},...(sheet.cells||[]).filter(cell=>cell.formula===undefined||cell.formula===null).map(cell=>({label:`${sheet.name||sheet.part} · ${cell.cell} · ${cell.text||'(blank)'}`,anchor:{kind:'xlsx_cell',part:sheet.part,cell:cell.cell,sourceText:cell.text||'',...pins}}))])];}
  function officeAnchorOptions(filter='',mode='scalar',selected=''){const candidates=officeAnchors(mode),matches=candidates.map((row,index)=>({...row,index})).filter(row=>row.label.toLowerCase().includes(filter.trim().toLowerCase())),shown=matches.slice(0,200);if(selected!==''&&!shown.some(row=>String(row.index)===String(selected))){const row=candidates[Number(selected)];if(row){shown.unshift({...row,index:Number(selected)});if(shown.length>200)shown.pop();}}return {html:`<option value="">Choose an exact original location</option>${shown.map(row=>option(row.index,row.label.slice(0,500),selected)).join('')}`,summary:`Showing ${Math.min(200,matches.length)} of ${matches.length} matching locations. Refine the search to find another location.`};}
